4	  const result = await database.query("SELECT id, title, closed FROM tickets", []);
5	  return { items: result.rows };
6	}
7	export async function closeTicket(id: string, database: TicketDatabase) {
8	  const result = await database.query("UPDATE tickets SET closed = TRUE WHERE id = $1 RETURNING id, closed", [id]);
9	  return result.rows[0];
10	}
